-- Synthetic metadata only: no file bytes, no employee creation, no real assessment. Entire transaction rolls back.
begin;set local lock_timeout='3s';set local statement_timeout='60s';
create temporary table prova_sub_dpi(actor uuid,azienda uuid,ordine uuid,altro_ordine uuid,sub uuid,sub2 uuid,w1 uuid,w2 uuid,w3 uuid,fase uuid,fase2 uuid,e1 uuid,e2 uuid,e3 uuid,e4 uuid);
insert into prova_sub_dpi select sp.user_id,sp.company_id,o.id,o2.id,gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid()
from public.staff_permissions sp join public.orders o on o.company_id=sp.company_id and o.deleted_at is null join public.orders o2 on o2.company_id=sp.company_id and o2.id<>o.id and o2.deleted_at is null where sp.can_view_sicurezza_cantiere and not sp.sola_lettura limit 1;
grant select on prova_sub_dpi to authenticated;
do $$begin if not exists(select 1 from prova_sub_dpi) then raise exception 'Fixture subappalto non disponibile';end if;end$$;
insert into public.subappaltatori_sicurezza(id,company_id,order_id,ragione_sociale) select x.id,f.azienda,f.ordine,'TEST DOTAZIONI ESTERNE' from prova_sub_dpi f cross join lateral(values(f.sub),(f.sub2))x(id);
insert into public.subappaltatori_operai(id,company_id,subappaltatore_id,nome,cognome,mansione) select x.id,f.azienda,x.sub,'TEST DOTAZIONE','Omonimo','Posatore' from prova_sub_dpi f cross join lateral(values(f.w1,f.sub),(f.w2,f.sub),(f.w3,f.sub2))x(id,sub);
insert into public.order_work_phases(id,company_id,order_id,name,position) select x.id,f.azienda,f.ordine,'TEST DPI ESTERNI FASE',x.pos from prova_sub_dpi f cross join lateral(values(f.fase,998),(f.fase2,999))x(id,pos);
insert into public.subappaltatori_assegnazioni(company_id,subappaltatore_id,operaio_id,order_id,fase_id,dal,al,attivita) select f.azienda,f.sub,x.w,f.ordine,x.fase,'2026-11-01','2026-11-30','TEST DOTAZIONE' from prova_sub_dpi f cross join lateral(values(f.w1,f.fase),(f.w1,f.fase2),(f.w2,f.fase2))x(w,fase);
insert into storage.objects(bucket_id,name) select 'fascicoli-cantiere',f.azienda::text||'/'||x.id::text||'/sintetico.pdf' from prova_sub_dpi f cross join lateral(values(f.e1),(f.e2),(f.e3),(f.e4))x(id);
insert into public.sicurezza_fascicolo(id,company_id,subappaltatore_id,operaio_id,order_id,fase_id,tipo,catalogo_id,catalogo_versione,titolo,file_path,file_name,stato,updated_at)
select x.id,f.azienda,f.sub,x.w,x.ordine,x.fase,'dpi','consegna_dpi',1,'TEST VERBALE DOTAZIONE',f.azienda::text||'/'||x.id::text||'/sintetico.pdf','sintetico.pdf','ricevuto','2026-10-01T00:00:00Z'
from prova_sub_dpi f cross join lateral(values(f.e1,f.w1,null::uuid,null::uuid),(f.e2,f.w2,null::uuid,null::uuid),(f.e3,f.w1,f.altro_ordine,null::uuid),(f.e4,f.w1,f.ordine,f.fase))x(id,w,ordine,fase);
select set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true) from prova_sub_dpi;set local role authenticated;
do $$declare f record;d jsonb;r jsonb;q jsonb;id1 uuid:=gen_random_uuid();id2 uuid:=gen_random_uuid();id3 uuid:=gen_random_uuid();req uuid:=gen_random_uuid();token text;prima jsonb;impronta text;begin
 select * into f from prova_sub_dpi;
 q:=public.sub_dpi_quadro(f.azienda,f.sub,f.ordine,'2026-11-15',f.fase,null);
 if jsonb_array_length(q->'addetti')<>1 or q->'addetti'->0->>'id'<>f.w1::text then raise exception 'ASSERT: fase non delimita gli addetti';end if;
 if exists(select 1 from jsonb_array_elements(q->'evidenze')e where e->>'id' in (f.e2::text,f.e3::text)) then raise exception 'ASSERT: verbale collega o altra commessa tra i pertinenti';end if;
 if q::text like '%file_path%' or q::text like '%telefono%' then raise exception 'ASSERT: proiezione non minima';end if;
 token:=(select updated_at::text from public.sicurezza_fascicolo where id=f.e1);
 impronta:=(select e->>'impronta' from jsonb_array_elements(q->'evidenze')e where e->>'id'=f.e1::text);
 d:=jsonb_build_object('tipo','casco','marca','TEST','taglia','M','matricola','EXT-TEST','consegnato_il','2026-11-15','scade_il',null,'stato','in_use','restituito_il',null,'note','TEST DPI ESTERNO ROLLBACK','annullata',false,'motivo','Registrazione sintetica con riferimento','evidenza_id',f.e1,'evidenza_attesa',token);
 d:=d||jsonb_build_object('evidenza_impronta',impronta);
 begin perform public.sub_dpi_salva(id1,f.azienda,f.sub,f.w1,f.ordine,'2026-11-15',f.fase,null,req,jsonb_set(d,'{evidenza_id}',to_jsonb(f.e2)));raise exception 'ASSERT: verbale di omonimo';exception when raise_exception then if sqlerrm<>'Verbale non appartenente al titolare' then raise;end if;end;
 begin perform public.sub_dpi_salva(id1,f.azienda,f.sub,f.w1,f.ordine,'2026-11-15',f.fase,null,req,jsonb_set(d||jsonb_build_object('evidenza_impronta',(select e->>'impronta' from jsonb_array_elements(public.sub_dpi_quadro(f.azienda,f.sub,null,'2026-11-15',null,f.w1)->'evidenze')e where e->>'id'=f.e3::text)),'{evidenza_id}',to_jsonb(f.e3)));raise exception 'ASSERT: verbale altra commessa';exception when raise_exception then if sqlerrm not like 'Il verbale non è pertinente%' then raise;end if;end;
 begin perform public.sub_dpi_salva(id1,f.azienda,f.sub,f.w2,f.ordine,'2026-11-15',f.fase,null,req,d);raise exception 'ASSERT: addetto altra fase';exception when serialization_failure then null;end;
 begin perform public.sub_dpi_salva(id1,f.azienda,f.sub,f.w3,null,'2026-11-15',null,null,req,d);raise exception 'ASSERT: addetto altra impresa';exception when raise_exception then if sqlerrm<>'Operaio non appartenente all’impresa' then raise;end if;end;
 begin perform public.sub_dpi_salva(id1,f.azienda,f.sub,f.w1,f.ordine,'2026-11-15',f.fase,null,req,jsonb_set(d,'{consegnato_il}','"tomorrow"'));raise exception 'ASSERT: data relativa';exception when raise_exception then if sqlerrm<>'Usa date nel formato AAAA-MM-GG' then raise;end if;end;
 r:=public.sub_dpi_salva(id1,f.azienda,f.sub,f.w1,f.ordine,'2026-11-15',f.fase,null,req,d);
 if (r->>'versione')::integer<>1 or r->'evidenza_snapshot'->>'stato'<>'ricevuto' or r::text like '%file_path%' then raise exception 'ASSERT: snapshot o versione non corretti';end if;
 if public.sub_dpi_salva(id1,f.azienda,f.sub,f.w1,f.ordine,'2026-11-15',f.fase,null,req,d)<>r or (select count(*) from public.subappaltatori_dpi_eventi where consegna_id=id1)<>1 then raise exception 'ASSERT: retry duplicato';end if;
 begin perform public.sub_dpi_salva(id1,f.azienda,f.sub,f.w1,f.ordine,'2026-11-15',f.fase,1,gen_random_uuid(),jsonb_set(jsonb_set(d,'{annullata}','true'),'{evidenza_id}',to_jsonb(f.e2)));raise exception 'ASSERT: annullamento con verbale di un altro operaio';exception when raise_exception then if sqlerrm<>'Verbale non appartenente al titolare' then raise;end if;end;
 begin perform public.sub_dpi_salva(id1,f.azienda,f.sub,f.w1,f.ordine,'2026-11-15',f.fase,null,req,jsonb_set(d,'{marca}','"Diversa"'));raise exception 'ASSERT: richiesta per altri dati';exception when serialization_failure then null;end;
 begin perform public.sub_dpi_salva(id1,f.azienda,f.sub,f.w1,f.ordine,'2026-11-15',f.fase,0,gen_random_uuid(),d);raise exception 'ASSERT: versione vecchia';exception when serialization_failure then null;end;
 prima:=r;
 update public.sicurezza_fascicolo set titolo='TEST VERBALE MODIFICATO' where id=f.e1;
 q:=public.sub_dpi_quadro(f.azienda,f.sub,f.ordine,'2026-11-15',f.fase,f.w1);
 if not (q->'addetti'->0->'consegne'->0->>'verbale_cambiato')::boolean then raise exception 'ASSERT: aggiornamento verbale nascosto';end if;
 begin perform public.sub_dpi_apri_verbale(f.azienda,f.sub,f.w1,f.e1,f.ordine,'2026-11-15',f.fase,impronta);raise exception 'ASSERT: apertura riferimento obsoleto';exception when raise_exception then if sqlerrm not like 'Verbale cambiato o non pertinente%' then raise;end if;end;
 begin perform public.sub_dpi_salva(id1,f.azienda,f.sub,f.w1,f.ordine,'2026-11-15',f.fase,1,gen_random_uuid(),d);raise exception 'ASSERT: verbale cambiato accettato';exception when serialization_failure then null;end;
 if (select dopo from public.subappaltatori_dpi_eventi where consegna_id=id1 and versione=1)<>prima then raise exception 'ASSERT: evento precedente riscritto';end if;
 -- Cancelling preserves the old reference without pretending it is a fresh review.
 r:=public.sub_dpi_salva(id1,f.azienda,f.sub,f.w1,f.ordine,'2026-11-15',f.fase,1,gen_random_uuid(),jsonb_set(jsonb_set(d,'{annullata}','true'),'{motivo}','"Annullamento di prova senza perdere storico"'));
 if not (r->>'annullata')::boolean or r->'evidenza_snapshot'<>prima->'evidenza_snapshot' then raise exception 'ASSERT: annullamento perde il riferimento storico';end if;
 begin perform public.sub_dpi_salva(id1,f.azienda,f.sub,f.w1,f.ordine,'2026-11-15',f.fase,2,gen_random_uuid(),d);raise exception 'ASSERT: ripristino senza rilettura';exception when serialization_failure then null;end;
 d:=jsonb_set(d,'{evidenza_attesa}',to_jsonb((select updated_at::text from public.sicurezza_fascicolo where id=f.e1)));
 d:=d||jsonb_build_object('evidenza_impronta',(select e->>'impronta' from jsonb_array_elements(q->'evidenze')e where e->>'id'=f.e1::text));
 r:=public.sub_dpi_salva(id1,f.azienda,f.sub,f.w1,f.ordine,'2026-11-15',f.fase,2,gen_random_uuid(),d);
 if (r->>'annullata')::boolean or (r->>'versione')::integer<>3 then raise exception 'ASSERT: ripristino';end if;
 if public.sub_dpi_apri_verbale(f.azienda,f.sub,f.w1,f.e1,f.ordine,'2026-11-15',f.fase,d->>'evidenza_impronta') is distinct from (select file_path from public.sicurezza_fascicolo where id=f.e1) then raise exception 'ASSERT: percorso verbale autorizzato';end if;
 begin perform public.sub_dpi_apri_verbale(f.azienda,f.sub,f.w2,f.e1,f.ordine,'2026-11-15',f.fase,d->>'evidenza_impronta');raise exception 'ASSERT: apertura di altro titolare';exception when raise_exception then if sqlerrm not like 'Verbale cambiato o non pertinente%' then raise;end if;end;
 -- A receipt from another case can be catalogued globally, but does not cover this case.
 d:=jsonb_set(jsonb_set(d,'{evidenza_id}',to_jsonb(f.e3)),'{evidenza_attesa}',to_jsonb((select updated_at::text from public.sicurezza_fascicolo where id=f.e3)));
 d:=d||jsonb_build_object('evidenza_impronta',(select e->>'impronta' from jsonb_array_elements(public.sub_dpi_quadro(f.azienda,f.sub,null,'2026-11-15',null,f.w1)->'evidenze')e where e->>'id'=f.e3::text));
 perform public.sub_dpi_salva(id2,f.azienda,f.sub,f.w1,null,'2026-11-15',null,null,gen_random_uuid(),d);
 q:=public.sub_dpi_quadro(f.azienda,f.sub,f.ordine,'2026-11-15',f.fase,f.w1);
 if exists(select 1 from jsonb_array_elements(q->'addetti'->0->'consegne')c where c->>'id'=id2::text and (c->>'verbale_pertinente')::boolean) then raise exception 'ASSERT: verbale altra commessa promosso';end if;
 d:=jsonb_set(d||jsonb_build_object('evidenza_impronta',(select e->>'impronta' from jsonb_array_elements(public.sub_dpi_quadro(f.azienda,f.sub,null,'2026-11-15',null,f.w1)->'evidenze')e where e->>'id'=f.e4::text)),'{evidenza_id}',to_jsonb(f.e4));
 perform public.sub_dpi_salva(id3,f.azienda,f.sub,f.w1,null,'2026-11-15',null,null,gen_random_uuid(),d);
 q:=public.sub_dpi_quadro(f.azienda,f.sub,f.ordine,'2026-11-15',f.fase2,f.w1);
 if exists(select 1 from jsonb_array_elements(q->'addetti'->0->'consegne')c where c->>'id'=id3::text and (c->>'verbale_pertinente')::boolean) then raise exception 'ASSERT: verbale di altra fase promosso';end if;
 update public.sicurezza_fascicolo set file_name=null where id=f.e1;
 q:=public.sub_dpi_quadro(f.azienda,f.sub,f.ordine,'2026-11-15',f.fase,f.w1);
 if exists(select 1 from jsonb_array_elements(q->'addetti'->0->'consegne')c where c->>'id'=id1::text and (c->>'verbale_pertinente')::boolean) then raise exception 'ASSERT: nome del file mancante promosso come disponibile';end if;
 begin update public.sicurezza_fascicolo set operaio_id=f.w2 where id=f.e1;raise exception 'ASSERT: verbale trasferibile a un collega';exception when raise_exception then if sqlerrm not like 'Il verbale è collegato%' then raise;end if;end;
 begin update public.subappaltatori_dpi_consegne set operaio_id=f.w2 where id=id1;raise exception 'ASSERT: scrittura diretta API';exception when insufficient_privilege then null;end;
 begin delete from public.subappaltatori_dpi_eventi where consegna_id=id1;raise exception 'ASSERT: audit cancellabile';exception when insufficient_privilege then null;end;
 if exists(select 1 from public.employee_dpi_consegne where employee_id in (f.w1,f.w2,f.w3)) or exists(select 1 from public.employees where id in (f.w1,f.w2,f.w3)) then raise exception 'ASSERT: operai esterni fusi con dipendenti';end if;
end$$;
reset role;
do $$declare f record;id1 uuid;begin select * into f from prova_sub_dpi;select id into id1 from public.subappaltatori_dpi_consegne where operaio_id=f.w1 limit 1;
 begin update public.subappaltatori_dpi_consegne set operaio_id=f.w2 where id=id1;raise exception 'ASSERT: titolare spostato';exception when raise_exception then if sqlerrm not like 'La consegna esterna non si trasferisce%' then raise;end if;end;
 begin delete from public.subappaltatori_dpi_eventi where consegna_id=id1;raise exception 'ASSERT: audit mutabile SQL ordinario';exception when raise_exception then if sqlerrm not like 'Lo storico delle consegne DPI non si modifica%' then raise;end if;end;
end$$;
update public.staff_permissions set sola_lettura=true where user_id=(select actor from prova_sub_dpi) and company_id=(select azienda from prova_sub_dpi);
set local role authenticated;
do $$declare f record;begin select * into f from prova_sub_dpi;
 begin perform public.sub_dpi_salva(gen_random_uuid(),f.azienda,f.sub,f.w1,null,'2026-11-15',null,null,gen_random_uuid(),'{}');raise exception 'ASSERT: sola lettura';exception when insufficient_privilege then null;end;
 if not exists(select 1 from public.subappaltatori_dpi_eventi where subappaltatore_id=f.sub) then raise exception 'ASSERT: lettura storico autorizzata negata';end if;
end$$;reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',gen_random_uuid(),'role','authenticated')::text,true);set local role authenticated;
do $$declare f record;begin select * into f from prova_sub_dpi;
 if exists(select 1 from public.subappaltatori_dpi_consegne where company_id=f.azienda) or exists(select 1 from public.subappaltatori_dpi_eventi where company_id=f.azienda) then raise exception 'ASSERT: fuga dati';end if;
 begin perform public.sub_dpi_quadro(f.azienda,f.sub,null,'2026-11-15',null,null);raise exception 'ASSERT: RPC senza permesso';exception when insufficient_privilege then null;end;
 begin perform public.sub_dpi_apri_verbale(f.azienda,f.sub,f.w1,f.e1,null,'2026-11-15',null,'inventata');raise exception 'ASSERT: file senza permesso';exception when insufficient_privilege then null;end;
end$$;reset role;
select 'PASS: dotazioni esterne canoniche, titolare, contesto, verbale versionato, CAS, retry, annullamento, audit e RLS' esito;
rollback;
